import{_ as a,o as n,c as e,am as t}from"./chunks/framework._FJXuPhs.js";const h=JSON.parse('{"title":"GIT-分支管理","description":"","frontmatter":{"title":"GIT-分支管理","excerpt":"摘要","date":"2025-10-27 15:51:48","updated":"2025-10-27 15:51:48"},"headers":[],"relativePath":"环境部署&工具/部署&工具  版本控制工具/GIT-分支管理/index.md","filePath":"环境部署&工具/部署&工具  版本控制工具/GIT-分支管理/index.md","lastUpdated":null}'),i={name:"环境部署&工具/部署&工具  版本控制工具/GIT-分支管理/index.md"};function o(l,s,c,p,r,d){return n(),e("div",null,[...s[0]||(s[0]=[t(`<p>Git 中关于分支管理的基础操作：​<strong>​新建分支​</strong>​、​<strong>​切换分支​</strong>​ 和 ​<strong>​删除分支​</strong>​。这些是日常开发中使用频率极高的命令。</p><p>核心概念回顾：​**​</p><ul><li>​<strong>​分支 (Branch):​</strong>​ Git 的核心功能之一。它允许你在一个独立于主开发线（通常是 <code>main</code> 或 <code>master</code>）的路径上进行开发，不会影响主线代码。非常适合开发新功能、修复 Bug 或尝试新想法。</li><li>​<strong>​HEAD:​</strong>​ 一个特殊的指针，指向你当前正在工作的分支（或具体的提交）。当你切换分支时，<code>HEAD</code> 会跟着移动。</li><li>​<strong>​工作目录 (Working Directory):​</strong>​ 你电脑上看到的项目文件目录。</li><li>​<strong>​暂存区 (Staging Area / Index):​</strong>​ 准备提交的文件集合。</li></ul><hr><h4 id="新建分支" tabindex="-1">新建分支 <a class="header-anchor" href="#新建分支" aria-label="Permalink to &quot;新建分支&quot;">​</a></h4><p>创建一个新分支意味着你基于某个起点（通常是当前所在分支的最新提交）开辟了一条新的开发线。</p><p>​<strong>​命令：​</strong>​</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>git branch &lt;new-branch-name&gt;</span></span></code></pre></div><ul><li>​<strong>​<code>&lt;new-branch-name&gt;</code>:​</strong>​ 你想要创建的新分支的名称。选择一个​<strong>​有意义且描述性强​</strong>​的名字很重要（例如 <code>feature/user-authentication</code>, <code>bugfix/login-error</code>, <code>experiment/new-algorithm</code>）。</li><li>​<strong>​执行后：​</strong>​ <ul><li>在 Git 的内部数据库中创建了一个指向​<strong>​当前所在分支最新提交​</strong>​的新指针。</li><li>​<strong>​重要：这个命令 <em>不会</em> 自动切换到新分支！​</strong>​ 你仍然停留在原来的分支上。</li></ul></li></ul><p>​<strong>​示例：​</strong>​</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># 假设当前在 main 分支</span></span>
<span class="line"><span>git branch feature/add-search</span></span>
<span class="line"><span># 此时创建了名为 feature/add-search 的新分支，但 HEAD 仍然指向 main</span></span></code></pre></div><p>​<strong>​常用选项：​</strong>​</p><ul><li><p>​<strong>​<code>git checkout -b &lt;new-branch-name&gt;</code>:​</strong>​ 这是一个​<strong>​非常常用​</strong>​的快捷命令。它等价于先执行 <code>git branch &lt;new-branch-name&gt;</code> 然后立即执行 <code>git checkout &lt;new-branch-name&gt;</code>。一步完成创建并切换到新分支。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>git checkout -b feature/add-search</span></span>
<span class="line"><span># 创建 feature/add-search 分支并立即切换到它</span></span></code></pre></div></li></ul><hr><h4 id="切换分支" tabindex="-1">切换分支 <a class="header-anchor" href="#切换分支" aria-label="Permalink to &quot;切换分支&quot;">​</a></h4><p>切换分支意味着将你的​<strong>​工作目录​</strong>​和 ​<strong>​HEAD 指针​</strong>​移动到指定的分支。工作目录中的文件会自动更新，以匹配目标分支的最新提交状态。</p><p>​<strong>​命令：​</strong>​</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>git checkout &lt;branch-name&gt;</span></span></code></pre></div><ul><li>​<strong>​<code>&lt;branch-name&gt;</code>:​</strong>​ 你想要切换到的​<strong>​已存在​</strong>​分支的名称。</li><li>​<strong>​执行前注意事项：​</strong>​ <ul><li>​<strong>​工作目录必须干净！​</strong>​ 这是最重要的规则。在切换分支前： <ul><li>提交 (<code>git commit</code>) 你当前分支上所有希望保留的修改。</li><li>或者，使用 <code>git stash</code> 将未提交的修改暂时储藏起来（之后可以在其他分支恢复）。</li></ul></li><li>如果工作目录或暂存区有未提交的修改，并且这些修改与目标分支上的文件有冲突，Git 会阻止你切换，并提示你先处理这些修改（提交、储藏或丢弃）。</li></ul></li><li>​<strong>​执行后：​</strong>​ <ul><li><code>HEAD</code> 指针移动到 <code>&lt;branch-name&gt;</code> 分支。</li><li>工作目录中的文件被替换为目标分支的最新快照。</li><li>后续的提交操作将在新切换到的分支上进行。</li></ul></li></ul><p>​<strong>​示例：​</strong>​</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># 从 main 分支切换到已存在的 feature/add-search 分支</span></span>
<span class="line"><span>git checkout feature/add-search</span></span>
<span class="line"><span># 现在 HEAD 指向 feature/add-search，工作目录是 feature/add-search 的内容</span></span></code></pre></div><p>​<strong>​现代替代命令 (推荐)：​</strong>​</p><ul><li><p>​<strong>​<code>git switch &lt;branch-name&gt;</code>:​</strong>​ Git 2.23 版本引入了更专注于切换分支的命令 <code>git switch</code>，语义更清晰，与 <code>git checkout</code> 的部分功能（如恢复文件）分离，减少了混淆。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>git switch feature/add-search</span></span></code></pre></div></li></ul><hr><h4 id="删除分支" tabindex="-1">删除分支 <a class="header-anchor" href="#删除分支" aria-label="Permalink to &quot;删除分支&quot;">​</a></h4><p>当你完成了一个分支上的工作（例如，功能开发完毕并合并回主分支），或者决定放弃某个实验性分支时，可以删除它，以保持仓库的整洁。</p><p>​<strong>​命令：​</strong>​</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>git branch -d &lt;branch-name&gt;</span></span></code></pre></div><ul><li><p>​<strong>​<code>&lt;branch-name&gt;</code>:​</strong>​ 你想要删除的分支的名称。</p></li><li><p>​<strong>​重要限制：​</strong>​</p><ul><li>你​<strong>​不能​</strong>​删除你当前所在的分支（<code>HEAD</code> 指向的分支）。必须先切换到其他分支（如 <code>main</code>）。</li><li>如果目标分支包含​<strong>​尚未合并​</strong>​到当前分支（或你指定的其他分支）的更改，Git 会拒绝删除，以防止丢失工作。它会提示类似 <code>error: The branch &#39;branch-name&#39; is not fully merged</code> 的错误。</li></ul></li><li><p>​<strong>​强制删除 (慎用！):​</strong>​</p><ul><li><p>如果你确定要删除一个包含未合并更改的分支（比如一个彻底失败的实验），可以使用 <code>-D</code> (大写) 选项强制删除：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>git branch -D &lt;branch-name&gt;</span></span></code></pre></div></li><li><p>​<strong>​警告：​</strong>​ 强制删除会​<strong>​永久丢失​</strong>​该分支上所有未合并的提交！请确保你真的不再需要这些更改。</p></li></ul></li></ul><p>​<strong>​示例：​</strong>​</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># 1. 确保不在要删除的分支上 (比如先切回 main)</span></span>
<span class="line"><span>git switch main</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 2. 安全删除 (如果分支已合并)</span></span>
<span class="line"><span>git branch -d feature/add-search</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 3. 强制删除 (如果分支未合并且确定要丢弃)</span></span>
<span class="line"><span>git branch -D experiment/failed-idea</span></span></code></pre></div><hr><h4 id="常见场景-切换分支-总结" tabindex="-1">常见场景(切换分支-总结) <a class="header-anchor" href="#常见场景-切换分支-总结" aria-label="Permalink to &quot;常见场景(切换分支-总结)&quot;">​</a></h4><ol><li><p>​<strong>​开始新功能开发：​</strong>​</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>git checkout main           # 确保在基础分支 (如 main)</span></span>
<span class="line"><span>git pull                    # 获取最新代码</span></span>
<span class="line"><span>git checkout -b feature/xyz # 创建并切换到新功能分支 feature/xyz</span></span>
<span class="line"><span># ... 在 feature/xyz 上进行开发、提交 ...</span></span></code></pre></div></li><li><p>​<strong>​修复紧急 Bug：​</strong>​</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>git checkout main           # 确保在基础分支</span></span>
<span class="line"><span>git pull</span></span>
<span class="line"><span>git checkout -b hotfix/abc  # 创建并切换到热修复分支 hotfix/abc</span></span>
<span class="line"><span># ... 在 hotfix/abc 上修复 Bug、提交 ...</span></span></code></pre></div></li><li><p>​<strong>​完成分支工作后：​</strong>​</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>git checkout main           # 切换回主分支</span></span>
<span class="line"><span>git merge feature/xyz       # 将 feature/xyz 合并到 main (或通过 Pull Request)</span></span>
<span class="line"><span>git branch -d feature/xyz   # 删除已合并的 feature/xyz 分支</span></span></code></pre></div></li></ol><blockquote><p>其他</p></blockquote><p>查看分支信息</p><ul><li>​<strong>​<code>git branch</code>:​</strong>​ 列出所有本地分支。当前分支前面会有一个 <code>*</code> 号。</li><li>​<strong>​<code>git branch -v</code>:​</strong>​ 列出分支并显示每个分支最新的提交信息。</li><li>​<strong>​<code>git branch -a</code>:​</strong>​ 列出所有本地分支和远程跟踪分支 (以 <code>remotes/</code> 开头)。</li><li>​<strong>​<code>git log --oneline --decorate --graph --all</code>:​</strong>​ 以图形化方式查看所有分支的提交历史。</li></ul><p>关键要点</p><ol><li>​<strong>​<code>git branch &lt;name&gt;</code> 只创建不切换。​</strong>​</li><li>​<strong>​<code>git checkout -b &lt;name&gt;</code> 或 <code>git switch -c &lt;name&gt;</code> 是创建并切换的快捷方式。​</strong>​</li><li>​<strong>​切换分支 (<code>checkout</code> / <code>switch</code>) 前务必保证工作目录干净。​</strong>​</li><li>​<strong>​删除分支 (<code>branch -d</code>) 前确保：​</strong>​ <ul><li>不在该分支上。</li><li>该分支的更改已合并（除非强制删除 <code>-D</code>）。</li></ul></li><li>​<strong>​强制删除 (<code>-D</code>) 会丢失未合并的提交，务必谨慎！​</strong>​</li><li>​<strong>​使用 <code>git switch</code> 代替 <code>git checkout</code> 来切换分支是更现代、更清晰的做法。​</strong>​</li></ol><p>熟练掌握这些分支操作是高效使用 Git 进行协作开发的基础。记得经常使用 <code>git status</code> 和 <code>git branch</code> 来查看当前状态。</p>`,40)])])}const u=a(i,[["render",o]]);export{h as __pageData,u as default};
